-- harness-s1.sql (generated by supabase/tests/backlog-4263-sync2-s1/gen.py; do not hand-edit)
-- TEST DATABASE ONLY. This file ends in a rollback and must never be run on production.
-- BACKLOG-4263 sync 2.49, P1: run AFTER supabase/migrations/20261123100000_backlog_4263_one_computer.sql is applied (file md5 2d518f0ef92a29b30faab48f648fc702).
-- ONE call (~/.claude/bin/kt-sql harness-s1.sql) that ends in RAISE, so nothing persists. Order: guard (refuses any database
-- that is not the test database) -> applied check -> helpers and fixtures -> 29 controls, each in a subtransaction
-- that is undone -> 20 mutants, each proven installed before every control runs again under it -> the rollback file and
-- its post-check -> RAISE 'S1_RESULT <json>'. Afterwards: ~/.claude/bin/kt-sql -c "select extensions.pg_stat_statements_reset()".
-- It takes no table lock on an existing table except: row locks on the fixture rows and on the one switches row (held
-- until the final RAISE), and the rollback file's ACCESS EXCLUSIVE on cloud_autosave_settings and the three new tables,
-- taken in the last step only, right before the RAISE. lock_timeout 3s.
DO $guard4263s1$
DECLARE n bigint := 0;
BEGIN
  IF pg_catalog.to_regclass('public.pm_backlog_items') IS NOT NULL THEN
    EXECUTE 'SELECT count(*) FROM public.pm_backlog_items' INTO n;
  END IF;
  IF n > 100 OR coalesce((SELECT s.n_live_tup FROM pg_catalog.pg_stat_user_tables s WHERE s.relid = pg_catalog.to_regclass('public.pm_backlog_items')), 0) > 100 THEN
    RAISE EXCEPTION 'harness-s1.sql refuses to run: TEST DATABASE ONLY (production tracker rows present)';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM auth.users u WHERE md5(u.id::text) = '53a385187695375e2e8695625a20a77a') THEN
    RAISE EXCEPTION 'harness-s1.sql refuses to run: TEST DATABASE ONLY (test database marker absent)';
  END IF;
END
$guard4263s1$;
SET LOCAL lock_timeout = '3s';
DO $applied4263s1$
BEGIN
  IF (SELECT md5(prosrc) FROM pg_catalog.pg_proc WHERE oid = to_regprocedure('public.cloud_claim_install(uuid,uuid,boolean)')) IS DISTINCT FROM '93fe1f5c48855e5f70950dcb7b5fca09'
     OR (SELECT md5(prosrc) FROM pg_catalog.pg_proc WHERE oid = to_regprocedure('public.cloud_upsert_deal(uuid,jsonb)')) IS DISTINCT FROM '49fe9c6b681dadbc5311c30f4d2f472d' THEN
    RAISE EXCEPTION 'harness-s1.sql: migration 20261123100000 is not applied at this file''s text';
  END IF;
END
$applied4263s1$;

CREATE TEMP TABLE s1_out (k text PRIMARY KEY, v jsonb) ON COMMIT DROP;
CREATE TEMP TABLE s1_fx (k text PRIMARY KEY, v uuid) ON COMMIT DROP;
CREATE TEMP TABLE s1_sql (k text PRIMARY KEY, s text) ON COMMIT DROP;
CREATE FUNCTION pg_temp.rec(k text, v jsonb) RETURNS void LANGUAGE sql AS $h$
  INSERT INTO pg_temp.s1_out VALUES (k, v) ON CONFLICT (k) DO UPDATE SET v = excluded.v
$h$;
CREATE FUNCTION pg_temp.f(k text) RETURNS uuid LANGUAGE sql STABLE AS $h$ SELECT v FROM pg_temp.s1_fx WHERE s1_fx.k = f.k $h$;
CREATE FUNCTION pg_temp.s(k text) RETURNS text LANGUAGE sql STABLE AS $h$ SELECT v::text FROM pg_temp.s1_fx WHERE s1_fx.k = s.k $h$;
CREATE FUNCTION pg_temp.fx(n text) RETURNS uuid LANGUAGE sql IMMUTABLE AS $h$ SELECT md5('p4263:sync2-s1-harness:' || n)::uuid $h$;
CREATE FUNCTION pg_temp.h(t text) RETURNS text LANGUAGE sql IMMUTABLE AS $h$ SELECT encode(sha256(convert_to(t, 'UTF8')), 'hex') $h$;
CREATE FUNCTION pg_temp.j(t text) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE AS $h$
BEGIN RETURN t::jsonb; EXCEPTION WHEN OTHERS THEN RETURN to_jsonb(t); END $h$;
CREATE FUNCTION pg_temp.pass(c boolean, detail text) RETURNS text LANGUAGE sql IMMUTABLE AS $h$
  SELECT CASE WHEN coalesce(c, false) THEN 'PASS' ELSE 'FAIL: ' || coalesce(left(detail, 900), '-') END
$h$;
CREATE FUNCTION pg_temp.clear_claims() RETURNS void LANGUAGE plpgsql AS $h$
BEGIN
  PERFORM set_config('request.jwt.claims', '', true);
  PERFORM set_config('request.jwt.claim.sub', '', true);
  PERFORM set_config('request.jwt.claim.role', '', true);
END $h$;
-- One statement as an API role with the user's claims (own subtransaction); an error returns 'ERR <sqlstate> <message>'.
CREATE FUNCTION pg_temp.call_as(u uuid, q text, r text DEFAULT 'authenticated') RETURNS text LANGUAGE plpgsql AS $h$
DECLARE j jsonb;
BEGIN
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub', u, 'role', r)::text, true);
    PERFORM set_config('request.jwt.claim.sub', coalesce(u::text, ''), true);
    PERFORM set_config('request.jwt.claim.role', r, true);
    EXECUTE format('SET LOCAL ROLE %I', r);
    EXECUTE q INTO j;
    EXECUTE 'RESET ROLE';
    PERFORM pg_temp.clear_claims();
    RETURN coalesce(j::text, 'null');
  EXCEPTION WHEN OTHERS THEN
    EXECUTE 'RESET ROLE';
    PERFORM pg_temp.clear_claims();
    RETURN 'ERR ' || SQLSTATE || ' ' || left(SQLERRM, 200);
  END;
END $h$;
-- public.<fn>(args) as the fixture user; args is a format() list of %L placeholders.
CREATE FUNCTION pg_temp.call(fn text, args text, VARIADIC vals text[]) RETURNS jsonb LANGUAGE plpgsql AS $h$
DECLARE q text := 'SELECT to_jsonb(public.' || quote_ident(fn) || '(' || args || '))';
BEGIN
  q := format(q, VARIADIC vals);
  RETURN pg_temp.j(pg_temp.call_as(pg_temp.f('A'), q));
END $h$;
CREATE FUNCTION pg_temp.claim(inst text, rep boolean) RETURNS jsonb LANGUAGE sql AS $h$
  SELECT pg_temp.call('cloud_claim_install', '%L::uuid, %L::uuid, %L::boolean', pg_temp.s('A'), pg_temp.s(inst), rep::text)
$h$;
CREATE FUNCTION pg_temp.onoff(en boolean, inst text) RETURNS jsonb LANGUAGE sql AS $h$
  SELECT pg_temp.call('set_my_cloud_autosave', '%L::uuid, %L::boolean, %L::integer, %L::uuid', pg_temp.s('A'), en::text, '1',
                      CASE WHEN inst IS NULL THEN NULL ELSE pg_temp.s(inst) END)
$h$;
CREATE FUNCTION pg_temp.state() RETURNS jsonb LANGUAGE sql AS $h$
  SELECT pg_temp.j(pg_temp.call_as(pg_temp.f('A'), 'SELECT public.get_my_cloud_autosave_state()'))
$h$;
CREATE FUNCTION pg_temp.switch(on_ boolean) RETURNS void LANGUAGE sql AS $h$
  UPDATE public.cloud_release_switches SET one_computer = on_ WHERE id
$h$;
CREATE FUNCTION pg_temp.active() RETURNS uuid LANGUAGE sql AS $h$
  SELECT active_install_id FROM public.cloud_autosave_settings WHERE user_id = pg_temp.f('A')
$h$;
CREATE FUNCTION pg_temp.enabled() RETURNS boolean LANGUAGE sql AS $h$
  SELECT enabled FROM public.cloud_autosave_settings WHERE user_id = pg_temp.f('A')
$h$;
CREATE FUNCTION pg_temp.moves() RETURNS bigint LANGUAGE sql AS $h$
  SELECT count(*) FROM public.cloud_computer_moves WHERE owner_user_id = pg_temp.f('A')
$h$;
CREATE FUNCTION pg_temp.notices() RETURNS bigint LANGUAGE sql AS $h$
  SELECT count(*) FROM public.cloud_computer_move_notices WHERE user_id = pg_temp.f('A')
$h$;
CREATE FUNCTION pg_temp.deals() RETURNS bigint LANGUAGE sql AS $h$
  SELECT count(*) FROM public.cloud_deals WHERE owner_user_id = pg_temp.f('A')
$h$;
-- Fingerprint of everything the fixture user has online (rows and their versions, removal and save times).
CREATE FUNCTION pg_temp.fp() RETURNS text LANGUAGE sql AS $h$
  SELECT md5(concat_ws('|',
    (SELECT string_agg(concat_ws(',', d.id, d.version, d.removed_at, d.last_synced_at, d.last_full_sync_at, d.content_hash), ';' ORDER BY d.id)
       FROM public.cloud_deals d WHERE d.owner_user_id = pg_temp.f('A')),
    (SELECT string_agg(concat_ws(',', p.id, p.version, p.removed_at, p.content_hash), ';' ORDER BY p.id)
       FROM public.cloud_deal_parties p WHERE p.owner_user_id = pg_temp.f('A')),
    (SELECT string_agg(concat_ws(',', m.id, m.version, m.removed_at, m.content_hash), ';' ORDER BY m.id)
       FROM public.cloud_deal_messages m WHERE m.owner_user_id = pg_temp.f('A')),
    (SELECT string_agg(concat_ws(',', f.id, f.version, f.removed_at, f.blob_id), ';' ORDER BY f.id)
       FROM public.cloud_deal_files f WHERE f.owner_user_id = pg_temp.f('A')),
    (SELECT string_agg(concat_ws(',', b.id, b.uploaded_at, b.purge_requested_at), ';' ORDER BY b.id)
       FROM public.cloud_blobs b WHERE b.owner_user_id = pg_temp.f('A')),
    (SELECT count(*) FROM public.cloud_todo_ops o WHERE o.owner_user_id = pg_temp.f('A')),
    (SELECT count(*) FROM public.cloud_todo_history t WHERE t.owner_user_id = pg_temp.f('A')),
    (SELECT string_agg(concat_ws(',', c.id, c.change_seq, c.removed_at), ';' ORDER BY c.id)
       FROM public.cloud_deal_checklists c WHERE c.owner_user_id = pg_temp.f('A'))))
$h$;
CREATE FUNCTION pg_temp.nowt() RETURNS text LANGUAGE sql VOLATILE AS $h$
  SELECT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
$h$;
CREATE FUNCTION pg_temp.dp(inst text, lid text) RETURNS text LANGUAGE sql IMMUTABLE AS $h$
  SELECT jsonb_build_object('source_install_id', inst, 'local_id', lid, 'content_hash', pg_temp.h(lid))::text
$h$;
CREATE FUNCTION pg_temp.rows(lid text) RETURNS text LANGUAGE sql IMMUTABLE AS $h$
  SELECT jsonb_build_array(jsonb_build_object('local_id', lid, 'content_hash', pg_temp.h(lid)))::text
$h$;
CREATE FUNCTION pg_temp.mrows(lid text) RETURNS text LANGUAGE sql IMMUTABLE AS $h$
  SELECT jsonb_build_array(jsonb_build_object('local_id', lid, 'content_hash', pg_temp.h(lid), 'channel_kind', 'email',
                                              'hidden_from_export', false))::text
$h$;

INSERT INTO pg_temp.s1_sql VALUES ('backfill', $bf$
  UPDATE public.cloud_autosave_settings s
     SET active_install_id = w.source_install_id, active_since = now()
    FROM (SELECT DISTINCT ON (d.owner_user_id) d.owner_user_id, d.source_install_id
            FROM public.cloud_deals d
           WHERE d.removed_at IS NULL
           GROUP BY d.owner_user_id, d.source_install_id
           ORDER BY d.owner_user_id, max(d.last_synced_at) DESC, d.source_install_id) w        /*BACKFILL:latest*/
   WHERE s.user_id = w.owner_user_id AND s.enabled AND s.active_install_id IS NULL AND s.user_id IN (SELECT v FROM pg_temp.s1_fx WHERE k LIKE 'bf_%');            /*BACKFILL:scope*/
$bf$);

-- Fixture user A: licensed through an organization on the team plan, Keepr Cloud on (notice 1). Installs IA, IB, IC.
-- Deals dA (IA), dB (IB), dC (IC) with one party each and a message on dA and dB, one registered blob of IA, all saved
-- while one_computer is off; then IA claims (first computer). Backfill users bf_1 .. bf_6 (rows written directly).
DO $fx$
DECLARE A uuid := pg_temp.fx('A'); O uuid := pg_temp.fx('O'); r jsonb; n int;
BEGIN
  INSERT INTO pg_temp.s1_fx SELECT k, pg_temp.fx(k) FROM unnest(ARRAY['A', 'O', 'M', 'IA', 'IB', 'IC']) k;
  SET LOCAL session_replication_role = replica;
  INSERT INTO auth.users (id, email, aud, role, instance_id, raw_app_meta_data, raw_user_meta_data, created_at, updated_at)
  SELECT pg_temp.fx(k), 'p4263-s1-' || substr(md5('s1-harness'), 1, 8) || '-' || lower(k) || '@example.test', 'authenticated', 'authenticated',
         '00000000-0000-0000-0000-000000000000', '{"provider":"email"}', '{}', now(), now()
    FROM unnest(ARRAY['A', 'bf_1', 'bf_2', 'bf_3', 'bf_4', 'bf_5', 'bf_6']) k;
  INSERT INTO public.users (id, email, oauth_provider, oauth_id, display_name)
  VALUES (A, 'p4263-s1-' || substr(md5('s1-harness'), 1, 8) || '-a@example.test', 'email', A::text, 'Fixture s1') ON CONFLICT (id) DO NOTHING;
  INSERT INTO public.organizations (id, name, slug) VALUES (O, 'Fixture s1', 'p4263-s1-' || substr(md5('s1-harness'), 1, 8));
  INSERT INTO public.organization_members (id, organization_id, user_id, role, license_status) VALUES (pg_temp.fx('M'), O, A, 'agent', 'active');
  INSERT INTO public.organization_plans (organization_id, plan_id, feature_overrides)
  VALUES (O, (SELECT id FROM public.plans WHERE tier = 'team' ORDER BY sort_order, name LIMIT 1), '{"cloud_autosave_assignable":{"enabled":true}}');
  SET LOCAL session_replication_role = origin;
  UPDATE public.cloud_release_switches SET one_computer = false WHERE id;
  r := pg_temp.j(pg_temp.call_as(NULL, format('SELECT public.assign_member_addon(%L::uuid, %L::uuid, %L, true, NULL::timestamptz)', O, A, 'cloud_autosave'), 'service_role'));
  IF r ->> 'state' IS DISTINCT FROM 'assigned' THEN RAISE EXCEPTION 'FIXTURE assign failed: %', r; END IF;
  r := pg_temp.onoff(true, NULL);
  IF r ->> 'success' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'FIXTURE enable failed: %', r; END IF;
  FOREACH n IN ARRAY ARRAY[1, 2, 3] LOOP
    r := pg_temp.call('cloud_upsert_deal', '%L::uuid, %L::jsonb', A::text,
                      pg_temp.dp(pg_temp.s((ARRAY['IA', 'IB', 'IC'])[n]), 'fx-deal-' || n));
    IF r -> 'results' -> 0 ->> 'status' IS DISTINCT FROM 'applied' THEN RAISE EXCEPTION 'FIXTURE deal % failed: %', n, r; END IF;
    INSERT INTO pg_temp.s1_fx VALUES ((ARRAY['dA', 'dB', 'dC'])[n], (r -> 'results' -> 0 ->> 'cloud_id')::uuid);
    r := pg_temp.call('cloud_upsert_parties', '%L::uuid, %L::uuid, %L::uuid, %L::jsonb', A::text, pg_temp.f((ARRAY['IA', 'IB', 'IC'])[n])::text,
                      pg_temp.f((ARRAY['dA', 'dB', 'dC'])[n])::text, pg_temp.rows('fx-party-' || n));
    IF r -> 'results' -> 0 ->> 'status' IS DISTINCT FROM 'applied' THEN RAISE EXCEPTION 'FIXTURE party % failed: %', n, r; END IF;
    INSERT INTO pg_temp.s1_fx VALUES ((ARRAY['pA', 'pB', 'pC'])[n], (r -> 'results' -> 0 ->> 'cloud_id')::uuid);
  END LOOP;
  r := pg_temp.call('cloud_upsert_messages', '%L::uuid, %L::uuid, %L::uuid, %L::jsonb', A::text, pg_temp.f('IA')::text, pg_temp.f('dA')::text, pg_temp.mrows('fx-m-a'));
  IF r -> 'results' -> 0 ->> 'status' IS DISTINCT FROM 'applied' THEN RAISE EXCEPTION 'FIXTURE message failed: %', r; END IF;
  r := pg_temp.call('cloud_upsert_messages', '%L::uuid, %L::uuid, %L::uuid, %L::jsonb', A::text, pg_temp.f('IB')::text, pg_temp.f('dB')::text, pg_temp.mrows('fx-m-b'));
  r := pg_temp.call('cloud_register_blob', '%L::uuid, %L::uuid, %L::text, %L::bigint, %L::text', A::text, pg_temp.f('IA')::text,
                    pg_temp.h('fx-blob-a'), '10', NULL);
  IF r ->> 'state' IS DISTINCT FROM 'new' THEN RAISE EXCEPTION 'FIXTURE blob failed: %', r; END IF;
  INSERT INTO pg_temp.s1_fx VALUES ('bA', (r ->> 'blob_id')::uuid);
  UPDATE public.cloud_autosave_settings SET active_install_id = NULL, active_since = NULL WHERE user_id = A;
  r := pg_temp.claim('IA', false);
  IF r ->> 'ok' IS DISTINCT FROM 'true' OR pg_temp.active() IS DISTINCT FROM pg_temp.f('IA') THEN RAISE EXCEPTION 'FIXTURE claim failed: %', r; END IF;
  -- backfill users: settings and deals written directly (owner role); one deal per (user, install)
  INSERT INTO pg_temp.s1_fx SELECT k, pg_temp.fx(k) FROM unnest(ARRAY['bf_1', 'bf_2', 'bf_3', 'bf_4', 'bf_5', 'bf_6',
    'bf_1_i1', 'bf_1_i2', 'bf_1_i3', 'bf_2_i1', 'bf_2_i2', 'bf_3_i1', 'bf_3_i2', 'bf_4_i1', 'bf_6_i1', 'bf_6_i2']) k;
  INSERT INTO public.cloud_autosave_settings (user_id, enabled, notice_version, accepted_at, active_install_id)
  VALUES (pg_temp.f('bf_1'), true, 1, now(), NULL), (pg_temp.f('bf_2'), true, 1, now(), NULL), (pg_temp.f('bf_3'), true, 1, now(), NULL),
         (pg_temp.f('bf_4'), false, 1, now(), NULL), (pg_temp.f('bf_5'), true, 1, now(), NULL), (pg_temp.f('bf_6'), true, 1, now(), pg_temp.f('bf_6_i1'));
  INSERT INTO public.cloud_deals (owner_user_id, source_install_id, local_transaction_id, content_hash, last_synced_at, removed_at)
  VALUES (pg_temp.f('bf_1'), pg_temp.f('bf_1_i1'), 'bf-1-1', pg_temp.h('a'), now() - interval '3 days', NULL),
         (pg_temp.f('bf_1'), pg_temp.f('bf_1_i2'), 'bf-1-2', pg_temp.h('b'), now() - interval '1 day', NULL),
         (pg_temp.f('bf_1'), pg_temp.f('bf_1_i3'), 'bf-1-3', pg_temp.h('c'), now() - interval '2 days', NULL),
         (pg_temp.f('bf_2'), pg_temp.f('bf_2_i1'), 'bf-2-1', pg_temp.h('d'), timestamptz '2026-11-01 00:00:00+00', NULL),
         (pg_temp.f('bf_2'), pg_temp.f('bf_2_i2'), 'bf-2-2', pg_temp.h('e'), timestamptz '2026-11-01 00:00:00+00', NULL),
         (pg_temp.f('bf_3'), pg_temp.f('bf_3_i1'), 'bf-3-1', pg_temp.h('f'), now() - interval '2 days', NULL),
         (pg_temp.f('bf_3'), pg_temp.f('bf_3_i2'), 'bf-3-2', pg_temp.h('g'), now() - interval '1 hour', now()),
         (pg_temp.f('bf_4'), pg_temp.f('bf_4_i1'), 'bf-4-1', pg_temp.h('h'), now(), NULL),
         (pg_temp.f('bf_6'), pg_temp.f('bf_6_i2'), 'bf-6-2', pg_temp.h('i'), now(), NULL);
END
$fx$;

CREATE FUNCTION pg_temp.c_state_keys() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE v jsonb; ra jsonb; rb jsonb; before text; after text; x uuid; x_t timestamptz;
BEGIN
  v := pg_temp.state();
  RETURN pg_temp.pass((v ->> 'schema_version') = '1' AND (v ->> 'active_install_id') = pg_temp.f('IA')::text
                      AND jsonb_typeof(v -> 'switches' -> 'one_computer') = 'boolean'
                      AND jsonb_typeof(v -> 'switches' -> 'messages_upload') = 'boolean', v::text);
END $c$;
CREATE FUNCTION pg_temp.c1_push() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE v jsonb; ra jsonb; rb jsonb; before text; after text; x uuid; x_t timestamptz;
BEGIN
  PERFORM pg_temp.switch(true);
  before := pg_temp.fp();
  rb := pg_temp.call('cloud_todo_push', '%L::uuid, %L::uuid, %L::text, %L::jsonb', pg_temp.s('A'), pg_temp.s('IB'), pg_temp.nowt(), '[]');
  after := pg_temp.fp();
  ra := pg_temp.call('cloud_todo_push', '%L::uuid, %L::uuid, %L::text, %L::jsonb', pg_temp.s('A'), pg_temp.s('IA'), pg_temp.nowt(), '[]');
  RETURN pg_temp.pass((rb ->> 'error') = 'computer_not_active' AND (rb ->> 'ok') = 'false' AND before = after AND (ra ->> 'ok') = 'true',
                      jsonb_build_object('inactive', rb, 'active', ra, 'unchanged', before = after)::text);
END $c$;
CREATE FUNCTION pg_temp.c1_deal() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE v jsonb; ra jsonb; rb jsonb; before text; after text; x uuid; x_t timestamptz;
BEGIN
  PERFORM pg_temp.switch(true);
  before := pg_temp.fp();
  rb := pg_temp.call('cloud_upsert_deal', '%L::uuid, %L::jsonb', pg_temp.s('A'), pg_temp.dp(pg_temp.s('IB'), 'c1-deal-IB'));
  after := pg_temp.fp();
  ra := pg_temp.call('cloud_upsert_deal', '%L::uuid, %L::jsonb', pg_temp.s('A'), pg_temp.dp(pg_temp.s('IA'), 'c1-deal-IA'));
  RETURN pg_temp.pass((rb ->> 'error') = 'computer_not_active' AND (rb ->> 'ok') = 'false' AND before = after AND (ra ->> 'ok') = 'true' AND (ra -> 'results' -> 0 ->> 'status') = 'applied',
                      jsonb_build_object('inactive', rb, 'active', ra, 'unchanged', before = after)::text);
END $c$;
CREATE FUNCTION pg_temp.c1_parties() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE v jsonb; ra jsonb; rb jsonb; before text; after text; x uuid; x_t timestamptz;
BEGIN
  PERFORM pg_temp.switch(true);
  before := pg_temp.fp();
  rb := pg_temp.call('cloud_upsert_parties', '%L::uuid, %L::uuid, %L::uuid, %L::jsonb', pg_temp.s('A'), pg_temp.s('IB'), pg_temp.s('dB'), pg_temp.rows('c1-p-IB'));
  after := pg_temp.fp();
  ra := pg_temp.call('cloud_upsert_parties', '%L::uuid, %L::uuid, %L::uuid, %L::jsonb', pg_temp.s('A'), pg_temp.s('IA'), pg_temp.s('dA'), pg_temp.rows('c1-p-IA'));
  RETURN pg_temp.pass((rb ->> 'error') = 'computer_not_active' AND (rb ->> 'ok') = 'false' AND before = after AND (ra ->> 'ok') = 'true' AND (ra -> 'results' -> 0 ->> 'status') = 'applied',
                      jsonb_build_object('inactive', rb, 'active', ra, 'unchanged', before = after)::text);
END $c$;
