  before := pg_temp.fp();
  rb := pg_temp.call('cloud_upsert_files', '%L::uuid, %L::uuid, %L::uuid, %L::jsonb', pg_temp.s('A'), pg_temp.s('IB'), pg_temp.s('dB'), '[]');
