    IF v_bad IS NULL AND r ->> 'blob_sha256' IS NOT NULL AND ((r ->> 'blob_sha256') ~ '^[0-9a-f]{64}$') IS NOT TRUE THEN v_bad := 'blob_sha256'; END IF;
    IF v_bad IS NOT NULL THEN
